namespace emon;


public static class Gvectest {
    internal static int GtC(emon.Port.Cells @out, int c, int f) {
        return emon.Port.CellsAt(@out, (c * 16) + f);
    }
    internal static int GtPath(emon.Port.Cells pa, int kind, int flags, int fill, int stroke, int width, int x0, int y0, int x1, int y1) {
        // A painted path: its box, flags, colours and width; no geometry yet.
        int r = Evidence.PaNew(pa, 1, kind, x0, y0, x1, y1);
        Evidence.PaSet(pa, r, Evidence.PfFlags(), flags);
        Evidence.PaSet(pa, r, Evidence.PfFill(), fill);
        Evidence.PaSet(pa, r, Evidence.PfStroke(), stroke);
        Evidence.PaSet(pa, r, Evidence.PfWidth(), width);
        return r;
    }
    internal static int GtPt(emon.Port.Cells pa, emon.Port.Cells pts, int r, int x, int y, int op) {
        // A point of path r's geometry.
        if (Evidence.PaGet(pa, r, Evidence.PfPfirst()) < 0) {
            Evidence.PaSet(pa, r, Evidence.PfPfirst(), emon.Port.CellsLen(pts) / 3);
        }
        Evidence.PtAdd(pts, x, y, op);
        int n = Evidence.PaGet(pa, r, Evidence.PfPcount());
        Evidence.PaSet(pa, r, Evidence.PfPcount(), n + 1);
        return 0;
    }
    internal static int GtRe(emon.Port.Cells pa, emon.Port.Cells pts, int r, int x0, int y0, int x1, int y1) {
        // What `re` writes: a move, three lines, a close at the start.
        GtPt(pa, pts, r, x0, y0, Evidence.PoMove());
        GtPt(pa, pts, r, x1, y0, Evidence.PoLine());
        GtPt(pa, pts, r, x1, y1, Evidence.PoLine());
        GtPt(pa, pts, r, x0, y1, Evidence.PoLine());
        GtPt(pa, pts, r, x0, y0, Evidence.PoClose());
        return 0;
    }
    internal static int GtRun(emon.Port.Cells pa, emon.Port.Cells pts, emon.Port.Cells mk, emon.Port.Cells im, int mode, emon.Port.Cells @out) {
        emon.Port.CellsDrop(@out, 0);
        return Gvec.GvPage(pa, pts, mk, im, 0, emon.Port.CellsLen(pa) / 24, 0, emon.Port.CellsLen(im) / 20, mode, @out);
    }
    [Xunit.Fact]
    public static void TestARectangleWrittenAsFourLinesAndACloseIsARectangle() {
        // Skia writes a rectangle as a move, four lines (the last back to the start) and a close: six rows, not five
        emon.Port.Cells pa = emon.Port.NewCells();
        emon.Port.Cells pts = emon.Port.NewCells();
        emon.Port.Cells mk = emon.Port.NewCells();
        emon.Port.Cells im = emon.Port.NewCells();
        emon.Port.Cells @out = emon.Port.NewCells();
        int r = GtPath(pa, Evidence.PaOther(), Evidence.PgFilled(), 0, -1, 0, 1000, 4950, 21000, 5050);
        GtPt(pa, pts, r, 1000, 4950, Evidence.PoMove());
        GtPt(pa, pts, r, 21000, 4950, Evidence.PoLine());
        GtPt(pa, pts, r, 21000, 5050, Evidence.PoLine());
        GtPt(pa, pts, r, 1000, 5050, Evidence.PoLine());
        GtPt(pa, pts, r, 1000, 4950, Evidence.PoLine());
        GtPt(pa, pts, r, 1000, 4950, Evidence.PoClose());
        emon.Testport.AssertEq(GtRun(pa, pts, mk, im, Gvec.GvSegments(), @out), 1, "one rule");
        emon.Testport.AssertEq(GtC(@out, 0, 8), 1000, "from its left end");
        emon.Testport.AssertEq(GtC(@out, 0, 10), 21000, "to its right end");
        emon.Testport.AssertEq(GtC(@out, 0, 12), 100, "one point thick");
    }
