    [Xunit.Fact]
    public static void TestAnArtifactAndAnImageAndABoxOnlyPath() {
        emon.Port.Cells pa = emon.Port.NewCells();
        emon.Port.Cells pts = emon.Port.NewCells();
        emon.Port.Cells mk = emon.Port.NewCells();
        emon.Port.Cells im = emon.Port.NewCells();
        emon.Port.Cells @out = emon.Port.NewCells();
        int m = Evidence.MkNew(mk, 1, 1, 0, 0, -1, 0);
        int r = GtPath(pa, Evidence.PaRect(), Evidence.PgFilled(), 0, -1, 0, 0, 4950, 20000, 5050);
        Evidence.MkSet(mk, m, 6, 1);
        Evidence.PaSet(pa, r, Evidence.PfMark(), m);
        emon.Testport.AssertEq(GtRun(pa, pts, mk, im, Gvec.GvSegments(), @out), 1, "a path with no geometry is read by its box");
        emon.Testport.AssertEq(GtC(@out, 0, 15) & Glayer.GqArtifactPagination(), Glayer.GqArtifactPagination(), "an /Artifact /Pagination mark is flagged");
        emon.Testport.AssertEq(GtC(@out, 0, 2), -1, "a box-only candidate has no point");
        // a thin visible image placement is a rule of colour -1; a hidden one is nothing
        emon.Port.CellsDrop(pa, 0);
        int i = Evidence.ImNew(im, 1, 0, 0, 20000, 100, 5, 1, 1);
        emon.Testport.AssertEq(GtRun(pa, pts, mk, im, Gvec.GvSegments(), @out), 1, "an image rule");
        emon.Testport.AssertEq(GtC(@out, 0, 13), -1, "of unknown colour");
        emon.Testport.AssertEq(GtC(@out, 0, 15), Glayer.GqFromImage(), "flagged from-image");
        emon.Testport.AssertEq(GtRun(pa, pts, mk, im, Gvec.GvLegacy(), @out), 0, "legacy has no image rules");
        Evidence.ImSet(im, i, Evidence.MfVis(), 5);
        emon.Testport.AssertEq(GtRun(pa, pts, mk, im, Gvec.GvSegments(), @out), 0, "a hidden image is not one");
    }
